  getProductSlugs,
  getRelatedProducts,
} from '@/lib/products'

export async function generateStaticParams() {
  return getProductSlugs().map((slug) => ({ slug }))
}

export default async function ProductPage({
  params,
  searchParams,
}: {
  params: Promise<{ slug: string }>
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>
}) {
  const { slug } = await params

  return (
    <main>
      <p>Signal Shop collection</p>
      <Suspense fallback={<p>Loading product details...</p>}>
        <ProductDetails slug={slug} searchParams={searchParams} />
      </Suspense>
    </main>
  )
}

async function ProductDetails({
  slug,
  searchParams,
}: {
  slug: string
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>
}) {
  const query = await searchParams
  const currency = typeof query.currency === 'string' ? query.currency : 'USD'
  const product = await getProduct(slug, currency)
  if (!product) notFound()

  return (
    <>
      <h1>{product.name}</h1>
      <p>{product.price}</p>
      <Suspense
        fallback={
          <section>
            <h2>Related products</h2>
            <p>Loading related products...</p>
          </section>
        }
      >
        <RelatedProducts slug={slug} />
      </Suspense>
    </>
  )
}

async function RelatedProducts({ slug }: { slug: string }) {
  const related = await getRelatedProducts(slug)

  return (
    <section>
      <h2>Related products</h2>
      {related.map((item) => (
        <p key={item.slug}>{item.name}</p>
      ))}
    </section>
  )
}

--- product data ---
import { cacheLife } from 'next/cache'

const products = {
  lamp: { slug: 'lamp', name: 'Brass lamp', usd: 120 },
  vase: { slug: 'vase', name: 'Stone vase', usd: 80 },
}

export function getProductSlugs() {
  return Object.keys(products)
}

async function getProductData(slug: string) {
  'use cache'
  cacheLife('hours')

  await new Promise((resolve) => setTimeout(resolve, 120))
  const product = products[slug as keyof typeof products]
  if (!product) return null
  return product
}

export async function getProduct(slug: string, currency: string) {
  const product = await getProductData(slug)
  if (!product) return null

  const rate = currency === 'EUR' ? 0.92 : 1
  return { ...product, price: `${currency} ${(product.usd * rate).toFixed(2)}` }
}

export async function getRelatedProducts(slug: string) {
  await new Promise((resolve) => setTimeout(resolve, 420))
  return Object.values(products).filter((product) => product.slug !== slug)
}
